const cmds = [
  ["version", "cat \"$STAMPED_ASSESSMENT_VERSION\""],
  ["manifest", "cat \"$STAMPED_DELIVERY_MANIFEST\""],
  ["receipt", "cat \"$STAMPED_WORKER_STOP_RECEIPT\""],
  ["target-limits", "cat \"$(dirname \"$STAMPED_JUDGE_TARGET\")/judge-target.json\""],
  ["runner-help", "\"$STAMPED_ASSESSMENT_PYTHON\" \"$STAMPED_ASSESSMENT_RUNNER\" --help"]
];
const results = await Promise.all(cmds.map(async ([n,cmd]) => [n, await tools.exec_command({cmd,yield_time_ms:10000,max_output_tokens:4000})]));
for (const [n,r] of results) text(`--- ${n} ---\n${r.output}`);

